const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nassauCounty = ee.Geometry.Polygon([[
    [-73.80, 40.55], // Southwestern point (approx)
    [-73.80, 40.95], // Northwestern point (approx)
    [-73.40, 40.95], // Northeastern point (approx)
    [-73.40, 40.55], // Southeastern point (approx)
    [-73.80, 40.55]
  ]]);

  const startMonth = 10;
  const endMonth = 10;
  const startDay = 1;
  const endDay = 23;

  const periods = {
    '2021': { start: ee.Date.fromYMD(2021, startMonth, startDay), end: ee.Date.fromYMD(2021, endMonth, endDay) },
    '2019': { start: ee.Date.fromYMD(2019, startMonth, startDay), end: ee.Date.fromYMD(2019, endMonth, endDay) },
    '2018': { start: ee.Date.fromYMD(2018, startMonth, startDay), end: ee.Date.fromYMD(2018, endMonth, endDay) },
  };

  const bandName = 'tropospheric_NO2_column_number_density';
  const scale = 1113.2; // Sentinel-5P native resolution is 7km x 3.5km, but varies. Use ~1km scale for region reduction.

  let no2_values = {};
  let pixel_counts = {};

  for (const year of Object.keys(periods)) {
    const period = periods[year];
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterBounds(nassauCounty)
      .filterDate(period.start, period.end)
      .select([bandName, 'qa_value'])
      .filter(ee.Filter.gt('qa_value', 0.75)); // Filter for good quality data

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${year}.`);
      console.log('C1');
      return;
    }

    const meanImage = collection.mean();

    // Check if the mean image is null (e.g., if all images were filtered out after QA)
    const hasImage = await meanImage.bandNames().getInfo().catch(() => null);
    if (!hasImage) {
      console.log(`Mean image is null for ${year} after QA filtering.`);
      console.log('C2');
      return;
    }

    // Calculate valid pixel count for the mean image
    const countReducer = ee.Reducer.count();
    const countResult = await meanImage.reduceRegion({
      reducer: countReducer,
      geometry: nassauCounty,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (countResult === null || countResult === 0) {
      console.log(`No valid pixels remaining for ${year} after QA filtering in region.`);
      console.log('C2');
      return;
    }
    pixel_counts[year] = countResult;

    // Calculate the mean NO2 value
    const meanValue = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nassauCounty,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (meanValue === null || isNaN(meanValue)) {
      console.log(`Calculation failed for ${year}. Result is null or NaN.`);
      console.log('C3');
      return;
    }
    no2_values[year] = meanValue;

    console.log(`${year} Images: ${collectionSize} (Val: ${no2_values[year] !== null ? no2_values[year].toFixed(7) : 'N/A'}, Pixels: ${pixel_counts[year]})`);
  }

  // Compare 2021 with 2019 and 2018
  const no2_2021 = no2_values['2021'];
  const no2_2019 = no2_values['2019'];
  const no2_2018 = no2_values['2018'];

  if (no2_2021 === undefined || no2_2019 === undefined || no2_2018 === undefined) {
    console.log("One or more yearly values are missing, likely due to a C1/C2/C3 error earlier.");
    console.log("C3");
    return;
  }

  // Question: 'Was the concentration ... lower between October 1-23, 2021 compared to the same period in 2019 and 2018?'
  const isLowerThan2019 = no2_2021 < no2_2019;
  const isLowerThan2018 = no2_2021 < no2_2018;

  if (isLowerThan2019 && isLowerThan2018) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
